<div class="card"><h2><?= e(t('Run scan')) ?></h2><div class="actions"><?php foreach(['fast'=>'Fast scan','standard'=>'Standard scan','deep'=>'Deep scan'] as $profile=>$label): ?><form method="post" action="/scan/start" style="display:inline"><input type="hidden" name="profile" value="<?= e($profile) ?>"><input type="hidden" name="scope" value="full"><select class="input" name="max_seconds"><option value="300"><?= e(t('5 min')) ?></option><option value="900"><?= e(t('15 min')) ?></option><option value="1800"><?= e(t('30 min')) ?></option><option value="0"><?= e(t('Unlimited/manual')) ?></option></select><button class="btn" <?= $scanDisabled?'disabled':'' ?>><?= e(t($label)) ?></button></form><?php endforeach ?></div><?php if($scanDisabled): ?><p class="muted"><b><?= e(t('Another scan is already running: Scan #:id.', ['id'=>$scanCtx['run']['id']??'pending'])) ?></b> <a href="/scan/active"><?= e(t('View active scan details')) ?></a>.</p><?php endif ?></div>
<div class="grid"><?php foreach ([['Last scan',$last['started_at']??'never'],['Profile',$last['profile']??'n/a'],['Users count',$users],['Sites count',$sites],['Files scanned',$last['files_scanned']??0],['New findings',$new],['Critical findings',$crit],['High findings',$high],['Quarantine count',$q]] as $c): ?><div class="card"><div class="muted"><?= e(t($c[0])) ?></div><h2><?= e(t((string)$c[1])) ?></h2></div><?php endforeach ?></div>

<div class="card"><h2><?= e(t('Scan history')) ?></h2><table><tr><th><?= e(t('ID')) ?></th><th><?= e(t('Profile')) ?></th><th><?= e(t('Scope')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Scanned files')) ?></th><th><?= e(t('Skipped media')) ?></th><th><?= e(t('Skipped dirs')) ?></th><th><?= e(t('Findings')) ?></th><th><?= e(t('Elapsed')) ?></th><th><?= e(t('Note')) ?></th></tr><?php foreach($scanRuns ?? [] as $r): $elapsed=($r['finished_at']&&$r['started_at'])?(strtotime($r['finished_at'])-strtotime($r['started_at'])).'s':t('running'); ?><tr><td><?= e($r['id']) ?></td><td><?= e(t($r['profile'] ?? 'fast')) ?></td><td><?= e(t($r['scope_type'])) ?> <?= e($r['scope_value'] ?? '') ?></td><td><?= e(t($r['status'])) ?></td><td><?= e($r['files_scanned']) ?></td><td><?= e($r['skipped_media'] ?? 0) ?></td><td><?= e($r['skipped_directories'] ?? 0) ?></td><td><?= e($r['findings_count']) ?></td><td><?= e($elapsed) ?></td><td><?= ($r['status']??'')==='completed_with_limit' ? '<span class="badge medium">'.e(t('Stopped by max seconds/files; scan may be incomplete')).'</span> ' : '' ?><?= e($r['error_text'] ?? '') ?></td></tr><?php endforeach ?></table></div>
<div class="card"><h2><?= e(t('Recent suspicious log events')) ?></h2><table class="log-table"><tr><th><?= e(t('Risk')) ?></th><th><?= e(t('Date/Time')) ?></th><th><?= e(t('IP')) ?></th><th><?= e(t('Method')) ?></th><th><?= e(t('URI')) ?></th><th><?= e(t('Raw / Actions')) ?></th></tr><?php foreach($logs as $l): $id='log-'.$l['id']; $dt=$l['created_at'] ? str_replace('-', '/', $l['created_at']) : ''; ?><tr><td><span class="badge <?= e($l['risk']) ?>"><?= e(t($l['risk'])) ?></span></td><td class="nowrap"><?= e($dt) ?></td><td class="nowrap"><?= e($l['ip']) ?></td><td><?= e($l['method']) ?></td><td class="uri-cell"><span title="<?= e($l['uri']) ?>"><?= e(mb_strimwidth($l['uri'] ?? '',0,90,'…')) ?></span><button class="btn small" onclick="copyText(<?= json_encode($l['uri'] ?? '') ?>);return false"><?= e(t('Copy')) ?></button></td><td><?= e(mb_strimwidth($l['raw_line'],0,100,'…')) ?> <button class="btn small" onclick="toggleDetails('<?= e($id) ?>');return false"><?= e(t('Details')) ?></button></td></tr><tr id="<?= e($id) ?>" class="details-row" style="display:none"><td colspan="6"><div class="details-grid"><div><b><?= e(t('Risk:')) ?></b> <?= e(t($l['risk'])) ?></div><div><b><?= e(t('Timestamp:')) ?></b> <?= e($dt) ?></div><div><b><?= e(t('IP:')) ?></b> <?= e($l['ip']) ?></div><div><b><?= e(t('Method:')) ?></b> <?= e($l['method']) ?></div><div><b><?= e(t('Host/Site:')) ?></b> <?= e($l['site_name'] ?? '') ?></div><div><b><?= e(t('Source log:')) ?></b> <?= e($l['log_path'] ?? '') ?><?= isset($l['line_number']) ? ':'.e($l['line_number']) : '' ?></div><div class="wide"><b><?= e(t('URI:')) ?></b> <code><?= e($l['uri']) ?></code> <button class="btn small" onclick="copyText(<?= json_encode($l['uri'] ?? '') ?>);return false"><?= e(t('Copy URI')) ?></button></div><div class="wide"><b><?= e(t('Matched reason:')) ?></b> <?= e($l['event_type'] ?? '') ?></div><div class="wide"><b><?= e(t('Raw log line:')) ?></b> <button class="btn small" onclick="copyText(<?= json_encode($l['raw_line'] ?? '') ?>);return false"><?= e(t('Copy raw')) ?></button><pre><?= e($l['raw_line']) ?></pre></div></div></td></tr><?php endforeach ?></table></div>
